def get_events(keywords, limit=None, **_extra):
    import json, os, datetime, time, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0159000" if __import__("os").path.isdir("./environment_mix/0159000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)
    now_iso = now.isoformat().replace("+00:00", "Z")

    # ---- helpers ----
    def _norm_kw(s):
        s = s.strip().lower()
        s = " ".join(s.split())
        return s

    def _gen_id(prefix):
        # deterministic-ish unique id with timestamp + random-ish hash
        raw = f"{prefix}_{now.timestamp()}_{os.getpid()}_{time.time_ns()}"
        h = hashlib.sha256(raw.encode("utf-8")).hexdigest()[:24]
        return f"{prefix}_{now.strftime('%Y%m%dT%H%M%S')}_{h}"

    def _parse_dt(v):
        if v is None:
            return None
        if isinstance(v, str):
            try:
                if v.endswith("Z"):
                    return datetime.datetime.fromisoformat(v.replace("Z", "+00:00"))
                return datetime.datetime.fromisoformat(v)
            except ValueError:
                return None
        return None

    def _same_utc_day(iso_ts, day_start):
        dt = _parse_dt(iso_ts)
        if dt is None:
            return False
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        dt_utc = dt.astimezone(datetime.timezone.utc)
        return day_start <= dt_utc < (day_start + datetime.timedelta(days=1))

    # ---- validate ----
    if not isinstance(keywords, str):
        return _err("VALIDATION_ERROR", "keywords must be a string")
    norm = _norm_kw(keywords)
    if not norm:
        return _err("VALIDATION_ERROR", "keywords must not be empty")
    if limit is None:
        limit = 10
    if not isinstance(limit, int):
        return _err("VALIDATION_ERROR", "limit must be an integer")
    if limit < 1 or limit > 100:
        return _err("VALIDATION_ERROR", "limit must be between 1 and 100", min=1, max=100)

    # ---- auth / key context ----
    # Tool signature carries no api_key; authenticate ambiently by finding any active key that can serve the request.
    api_keys = _load("api_keys.json")
    active_keys = [k for k in api_keys if isinstance(k, dict) and k.get("status") == "active"]
    if not active_keys:
        # no key in the store that can authorize requests
        return _err("UNAUTHORIZED", "No active API key available to authorize queries")

    # enforce per-key daily_limit by choosing a key that has remaining quota.
    search_queries = _load("search_queries.json")
    day_start = now.replace(hour=0, minute=0, second=0, microsecond=0)
    chosen_key = None
    for k in active_keys:
        dl = k.get("daily_limit")
        if not isinstance(dl, int):
            continue
        if dl <= 0:
            chosen_key = k
            break
        kid = k.get("id")
        used = 0
        for q in search_queries:
            if not isinstance(q, dict):
                continue
            if q.get("api_key_id") == kid and isinstance(q.get("created_at"), str) and _same_utc_day(q.get("created_at"), day_start):
                used += 1
        if used < dl:
            chosen_key = k
            break

    if chosen_key is None:
        # Since at least one active key exists but none have remaining quota
        # Return QUOTA_EXCEEDED (per business rules).
        # (Not RATE_LIMIT; daily_limit is quota.)
        # Also record a failed query attempt? Rule: each get_events call creates a search_queries row,
        # but revoked keys cannot create. Here we have active but over quota; create row with failed.
        # We can create the row with the least-over-limit key for audit; pick first active key.
        chosen_key = active_keys[0]
        qid = _gen_id("sq")
        qrow = {
            "id": qid,
            "api_key_id": chosen_key.get("id"),
            "keywords": keywords,
            "normalized_keywords": norm,
            "limit": int(limit),
            "status": "received",
            "error_message": None,
            "results_count": None,
            "execution_ms": None,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        search_queries.append(qrow)
        _save("search_queries.json", search_queries)

        # transition received -> failed exactly once
        qrow["status"] = "failed"
        qrow["error_message"] = "Daily query limit exceeded"
        qrow["results_count"] = 0
        qrow["execution_ms"] = int((time.time() - t0) * 1000)
        qrow["updated_at"] = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc).isoformat().replace("+00:00", "Z")
        _save("search_queries.json", search_queries)
        return _err("QUOTA_EXCEEDED", "Daily query limit exceeded")

    # ---- create search query row (received) ----
    qid = _gen_id("sq")
    qrow = {
        "id": qid,
        "api_key_id": chosen_key.get("id"),
        "keywords": keywords,
        "normalized_keywords": norm,
        "limit": int(limit),
        "status": "received",
        "error_message": None,
        "results_count": None,
        "execution_ms": None,
        "created_at": now_iso,
        "updated_at": now_iso,
    }
    search_queries.append(qrow)
    _save("search_queries.json", search_queries)

    # ---- run search ----
    try:
        events = _load("events.json")
        active_events = [e for e in events if isinstance(e, dict) and e.get("status") == "active"]

        # simple scoring: count keyword token occurrences in search_document + title boost
        tokens = [t for t in norm.split(" ") if t]
        def _text(e):
            sd = e.get("search_document")
            if isinstance(sd, str) and sd.strip():
                return sd.lower()
            # fallback
            parts = []
            for f in ("title", "description", "location", "organizer"):
                v = e.get(f)
                if isinstance(v, str):
                    parts.append(v)
            tp = e.get("topics")
            if isinstance(tp, list):
                parts.extend([x for x in tp if isinstance(x, str)])
            return " ".join(parts).lower()

        def _score(e):
            txt = _text(e)
            score = 0.0
            for t in tokens:
                if not t:
                    continue
                c = txt.count(t)
                score += float(c)
            title = e.get("title")
            if isinstance(title, str):
                ttl = title.lower()
                for t in tokens:
                    if t and t in ttl:
                        score += 2.0
            return score

        scored = []
        for e in active_events:
            s = _score(e)
            if s > 0:
                scored.append((s, e))
        scored.sort(key=lambda x: (x[0], x[1].get("updated_at") or "", x[1].get("id") or ""), reverse=True)

        top = scored[:limit]
        results = [e for _, e in top]

        # ---- write results rows (completed query) ----
        sqr = _load("search_query_results.json")
        existing_by_pair = set()
        existing_by_rank = set()
        for r in sqr:
            if not isinstance(r, dict):
                continue
            if r.get("search_query_id") == qid:
                existing_by_pair.add((r.get("search_query_id"), r.get("event_id")))
                existing_by_rank.add((r.get("search_query_id"), r.get("rank")))

        inserted = 0
        rank = 1
        for s, e in top:
            if rank > limit:
                break
            eid = e.get("id")
            if not isinstance(eid, str) or not eid:
                rank += 1
                continue
            if (qid, eid) in existing_by_pair or (qid, rank) in existing_by_rank:
                # should not happen for new qid; skip to preserve uniqueness
                rank += 1
                continue
            rid = _gen_id("sqr")
            row = {
                "id": rid,
                "search_query_id": qid,
                "event_id": eid,
                "rank": rank,
                "score": float(s),
                "created_at": now_iso,
                "updated_at": now_iso,
            }
            sqr.append(row)
            inserted += 1
            rank += 1

        if inserted > 0:
            _save("search_query_results.json", sqr)

        # ---- transition query to completed exactly once ----
        qrow["status"] = "completed"
        qrow["results_count"] = len(results)
        qrow["execution_ms"] = int((time.time() - t0) * 1000)
        qrow["updated_at"] = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc).isoformat().replace("+00:00", "Z")
        _save("search_queries.json", search_queries)

        return {
            "search_query": {
                "id": qid,
                "keywords": keywords,
                "normalized_keywords": norm,
                "limit": int(limit),
                "status": qrow["status"],
                "results_count": qrow["results_count"],
                "execution_ms": qrow["execution_ms"],
                "created_at": qrow["created_at"],
                "updated_at": qrow["updated_at"],
            },
            "events": results,
            "count": len(results),
            "limit": int(limit),
        }

    except (TypeError, ValueError) as e:
        # ---- transition query to failed exactly once ----
        qrow["status"] = "failed"
        qrow["error_message"] = str(e)
        qrow["results_count"] = 0
        qrow["execution_ms"] = int((time.time() - t0) * 1000)
        qrow["updated_at"] = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc).isoformat().replace("+00:00", "Z")
        _save("search_queries.json", search_queries)
        return _err("VALIDATION_ERROR", "Failed to execute search", detail=str(e))

def get_event(id, **_extra):
    import json, os, datetime

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0159000" if __import__("os").path.isdir("./environment_mix/0159000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    if not isinstance(id, str) or not id.strip():
        return _err("VALIDATION_ERROR", "id must be a non-empty string")

    # Ambient auth: allow if there exists any active API key in the system.
    api_keys = _load("api_keys.json")
    if not any(isinstance(k, dict) and k.get("status") == "active" for k in api_keys):
        return _err("UNAUTHORIZED", "No active API key available to authorize access")

    events = _load("events.json")
    for e in events:
        if isinstance(e, dict) and e.get("id") == id:
            return {"event": e}
    return _err("NOT_FOUND", "Event not found", id=id)

def list_ingestion_jobs(status=None, source_name=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0159000" if __import__("os").path.isdir("./environment_mix/0159000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    # Ambient auth
    api_keys = _load("api_keys.json")
    if not any(isinstance(k, dict) and k.get("status") == "active" for k in api_keys):
        return _err("UNAUTHORIZED", "No active API key available to authorize access")

    allowed_status = {"queued", "running", "succeeded", "failed", "cancelled"}
    if status is not None:
        if not isinstance(status, str) or status not in allowed_status:
            return _err("VALIDATION_ERROR", "Invalid status", allowed=sorted(list(allowed_status)))
    if source_name is not None and (not isinstance(source_name, str) or not source_name.strip()):
        return _err("VALIDATION_ERROR", "source_name must be a non-empty string when provided")

    if limit is None:
        limit = 50
    if not isinstance(limit, int):
        return _err("VALIDATION_ERROR", "limit must be an integer")
    if limit < 1 or limit > 200:
        return _err("VALIDATION_ERROR", "limit must be between 1 and 200", min=1, max=200)

    start_index = 0
    if cursor is not None:
        if not isinstance(cursor, str) or not cursor:
            return _err("VALIDATION_ERROR", "cursor must be a non-empty string when provided")
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8")).decode("utf-8")
            if not raw.startswith("idx:"):
                return _err("VALIDATION_ERROR", "Invalid cursor")
            start_index = int(raw.split(":", 1)[1])
            if start_index < 0:
                return _err("VALIDATION_ERROR", "Invalid cursor index")
        except (ValueError, UnicodeDecodeError, base64.binascii.Error):
            return _err("VALIDATION_ERROR", "Invalid cursor")

    jobs = _load("ingestion_jobs.json")
    rows = [j for j in jobs if isinstance(j, dict)]

    if status is not None:
        rows = [j for j in rows if j.get("status") == status]
    if source_name is not None:
        rows = [j for j in rows if j.get("source_name") == source_name]

    def _sort_key(j):
        # reverse chronological by created_at, fallback updated_at then id
        ca = j.get("created_at") if isinstance(j.get("created_at"), str) else ""
        ua = j.get("updated_at") if isinstance(j.get("updated_at"), str) else ""
        return (ca, ua, j.get("id") or "")

    rows.sort(key=_sort_key, reverse=True)

    total = len(rows)
    page = rows[start_index:start_index + limit]
    next_index = start_index + len(page)
    has_more = next_index < total
    next_cursor = None
    if has_more:
        next_cursor = base64.urlsafe_b64encode(f"idx:{next_index}".encode("utf-8")).decode("utf-8")

    return {
        "jobs": page,
        "page": {
            "limit": limit,
            "cursor": cursor,
            "next_cursor": next_cursor,
            "has_more": has_more,
            "total": total,
        },
    }

def get_ingestion_job(id, **_extra):
    import json, os, datetime, time, secrets

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0159000" if __import__("os").path.isdir("./environment_mix/0159000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0)

    def _now_iso():
        return _now().isoformat().replace("+00:00", "Z")

    def _unwrap_rows(data):
        # supports either raw list or {"rows":[...]} container
        if isinstance(data, dict) and isinstance(data.get("rows"), list):
            return data["rows"], True, data
        if isinstance(data, list):
            return data, False, None
        return [], False, None

    def _append_request_log(endpoint, status, latency_ms, error_code=None, credential_id=None):
        # only if file exists; schema doesn't declare it but service may include it
        path = os.path.join(_DB, "request_logs.json")
        if not os.path.exists(path):
            return
        reqlog = _load("request_logs.json")
        rows, wrapped, container = _unwrap_rows(reqlog)
        row = {
            "id": f"cfp_req_{int(time.time() * 1000)}_{secrets.token_hex(4)}",
            "endpoint": endpoint,
            "credential_id": credential_id,
            "status": status,
            "error_code": error_code,
            "latency_ms": int(latency_ms),
            "created_at": _now_iso(),
        }
        rows.append(row)
        if wrapped and isinstance(container, dict):
            container["rows"] = rows
            _save("request_logs.json", container)
        else:
            _save("request_logs.json", rows)

    t0 = time.time()
    endpoint = "get_ingestion_job"

    # Validate inputs
    if not isinstance(id, str):
        latency_ms = (time.time() - t0) * 1000
        _append_request_log(endpoint, "error", latency_ms, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "id must be a string")
    job_id = id.strip()
    if not job_id:
        latency_ms = (time.time() - t0) * 1000
        _append_request_log(endpoint, "error", latency_ms, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "id is required")

    # Ambient auth: caller is already authenticated; no further ACL model is provided in schema.
    # Only return UNAUTHORIZED if there is some explicit auth model and no valid context exists.
    # (No such model exists in this datastore/schema.)
    jobs_data = _load("ingestion_jobs.json")
    jobs, wrapped, container = _unwrap_rows(jobs_data)

    job = None
    for r in jobs:
        if isinstance(r, dict) and r.get("id") == job_id:
            job = r
            break

    if not job:
        latency_ms = (time.time() - t0) * 1000
        _append_request_log(endpoint, "error", latency_ms, error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Ingestion job not found", id=job_id)

    latency_ms = (time.time() - t0) * 1000
    _append_request_log(endpoint, "ok", latency_ms)
    return {"data": job}

def create_ingestion_job(source_name, source_url, **_extra):
    import json, os, datetime, time, re, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0159000" if __import__("os").path.isdir("./environment_mix/0159000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    # No request-log/usage collection defined in schema for this service.

    # Validate input
    if not isinstance(source_name, str):
        return _err("VALIDATION_ERROR", "source_name must be a string")
    if not isinstance(source_url, str):
        return _err("VALIDATION_ERROR", "source_url must be a string")

    sn = source_name.strip()
    su = source_url.strip()

    if not sn:
        return _err("VALIDATION_ERROR", "source_name is required")
    if not su:
        return _err("VALIDATION_ERROR", "source_url is required")
    if len(sn) > 2000 or len(su) > 5000:
        return _err("VALIDATION_ERROR", "source_name/source_url is too long")

    # Basic URL-ish validation (service accepts feeds; keep permissive)
    if not re.match(r"^https?://", su, re.IGNORECASE):
        return _err("VALIDATION_ERROR", "source_url must be an absolute http(s) URL")

    # AUTH: Ambient. No explicit credential parameter for these tools.
    # Per contract: do not refuse well-formed calls merely due to missing auth parameter.
    # Therefore, allow.

    jobs = _load("ingestion_jobs.json")

    now = datetime.datetime.now(datetime.timezone.utc).isoformat()

    # Generate id with stable prefix
    new_id = f"ing_{uuid.uuid4().hex}"

    row = {
        "id": new_id,
        "source_name": sn,
        "source_url": su,
        "status": "queued",
        "started_at": None,
        "finished_at": None,
        "events_upserted": 0,
        "events_skipped": 0,
        "error_message": None,
        "created_at": now,
        "updated_at": now,
    }

    jobs.append(row)
    _save("ingestion_jobs.json", jobs)

    latency_ms = int((time.time() - t0) * 1000)
    return {
        "job": row,
        "meta": {
            "latency_ms": latency_ms
        }
    }

def cancel_ingestion_job(id, **_extra):
    import json, os, datetime, time, secrets

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0159000" if __import__("os").path.isdir("./environment_mix/0159000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0)

    def _now_iso():
        return _now().isoformat().replace("+00:00", "Z")

    def _unwrap_rows(data):
        if isinstance(data, dict) and isinstance(data.get("rows"), list):
            return data["rows"], True, data
        if isinstance(data, list):
            return data, False, None
        return [], False, None

    def _append_request_log(endpoint, status, latency_ms, error_code=None, credential_id=None):
        path = os.path.join(_DB, "request_logs.json")
        if not os.path.exists(path):
            return
        reqlog = _load("request_logs.json")
        rows, wrapped, container = _unwrap_rows(reqlog)
        row = {
            "id": f"cfp_req_{int(time.time() * 1000)}_{secrets.token_hex(4)}",
            "endpoint": endpoint,
            "credential_id": credential_id,
            "status": status,
            "error_code": error_code,
            "latency_ms": int(latency_ms),
            "created_at": _now_iso(),
        }
        rows.append(row)
        if wrapped and isinstance(container, dict):
            container["rows"] = rows
            _save("request_logs.json", container)
        else:
            _save("request_logs.json", rows)

    t0 = time.time()
    endpoint = "cancel_ingestion_job"

    # Validate inputs
    if not isinstance(id, str):
        latency_ms = (time.time() - t0) * 1000
        _append_request_log(endpoint, "error", latency_ms, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "id must be a string")
    job_id = id.strip()
    if not job_id:
        latency_ms = (time.time() - t0) * 1000
        _append_request_log(endpoint, "error", latency_ms, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "id is required")

    # Ambient auth: caller is already authenticated; schema provides no per-user ACLs.
    jobs_data = _load("ingestion_jobs.json")
    jobs, wrapped, container = _unwrap_rows(jobs_data)

    idx = None
    job = None
    for i, r in enumerate(jobs):
        if isinstance(r, dict) and r.get("id") == job_id:
            idx = i
            job = r
            break

    if job is None:
        latency_ms = (time.time() - t0) * 1000
        _append_request_log(endpoint, "error", latency_ms, error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Ingestion job not found", id=job_id)

    status = job.get("status")
    # Business rule: permitted only when queued or running.
    if status not in ("queued", "running"):
        latency_ms = (time.time() - t0) * 1000
        _append_request_log(endpoint, "error", latency_ms, error_code="CONFLICT")
        return _err(
            "CONFLICT",
            "Ingestion job cannot be cancelled from its current state; permitted only when status is 'queued' or 'running'.",
            id=job_id,
            status=status,
        )

    now_iso = _now_iso()
    # Transition: queued/running -> cancelled (and timestamps as appropriate)
    job = dict(job)  # avoid mutating the referenced dict unexpectedly
    job["status"] = "cancelled"
    # keep existing started_at if any; but if running with no started_at, set it (best-effort)
    if status == "running" and not job.get("started_at"):
        job["started_at"] = now_iso
    job["finished_at"] = now_iso
    job["updated_at"] = now_iso

    jobs[idx] = job
    if wrapped and isinstance(container, dict):
        container["rows"] = jobs
        _save("ingestion_jobs.json", container)
    else:
        _save("ingestion_jobs.json", jobs)

    latency_ms = (time.time() - t0) * 1000
    _append_request_log(endpoint, "ok", latency_ms)
    return {"data": job}

def get_me(api_key=None, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0159000" if __import__("os").path.isdir("./environment_mix/0159000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    keys = _load("api_keys.json")
    queries = _load("search_queries.json")

    resolved_key = None
    presented = None

    if api_key is not None:
        if not isinstance(api_key, str):
            return _err("VALIDATION_ERROR", "api_key must be a string")
        presented = api_key.strip()
        if presented == "":
            return _err("VALIDATION_ERROR", "api_key must not be blank when provided")

        # Authenticate by matching the client-visible value against stored id OR key_hash
        # (Schema stores key_hash; contract requires not checking against a hash of plaintext that can't be known.
        # Here we treat api_key as matching either id or key_hash as a client-visible token in this local store.)
        for k in keys:
            if not isinstance(k, dict):
                continue
            if k.get("id") == presented or k.get("key_hash") == presented:
                resolved_key = k
                break

        if resolved_key is None:
            return _err("UNAUTHORIZED", "Invalid API key")

    # Identify caller:
    # - If api_key provided and resolved => identified as that key.
    # - If not provided => allow anonymous/local identity if any service context exists.
    #   However tool says raise UNAUTHORIZED if caller cannot be identified.
    #   We'll treat presence of at least one key in store as sufficient service identity context for anonymous.
    if resolved_key is None and api_key is None:
        if not isinstance(keys, list) or len(keys) == 0:
            return _err("UNAUTHORIZED", "Caller cannot be identified (no API key provided and no keys exist)")
        # Anonymous identity
    if resolved_key is not None and resolved_key.get("status") not in ("active", "revoked"):
        return _err("UNAUTHORIZED", "API key is not in a recognizable state")

    now_utc = datetime.datetime.now(datetime.timezone.utc)
    day_start = now_utc.replace(hour=0, minute=0, second=0, microsecond=0)
    day_end = day_start + datetime.timedelta(days=1)

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            return datetime.datetime.fromisoformat(s.replace("Z", "+00:00"))
        except Exception:
            return None

    usage_today = None
    quota = None
    remaining = None

    if resolved_key is not None:
        key_id = resolved_key.get("id")
        # Count search_queries created for this key for UTC day.
        cnt = 0
        for q in queries:
            if not isinstance(q, dict):
                continue
            if q.get("api_key_id") != key_id:
                continue
            dt = _parse_dt(q.get("created_at"))
            if dt is None:
                continue
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            if day_start <= dt < day_end:
                cnt += 1
        usage_today = cnt
        dl = resolved_key.get("daily_limit")
        quota = dl if isinstance(dl, int) else None
        if isinstance(quota, int) and quota >= 0:
            remaining = max(quota - usage_today, 0)
        else:
            remaining = None

    latency_ms = int((time.time() - t0) * 1000)

    identity = {
        "type": "api_key" if resolved_key is not None else "anonymous",
        "api_key": None,
    }
    if resolved_key is not None:
        identity["api_key"] = {
            "id": resolved_key.get("id"),
            "name": resolved_key.get("name"),
            "status": resolved_key.get("status"),
            "daily_limit": resolved_key.get("daily_limit"),
            "revoked_at": resolved_key.get("revoked_at"),
        }

    # Scopes not modeled in schema; return service-default.
    scopes = ["read:events", "search:events", "ingestion:jobs"]

    entitlements = {
        "scopes": scopes,
        "quota": {
            "period": "utc_day",
            "used": usage_today,
            "limit": quota,
            "remaining": remaining,
            "resets_at": day_end.isoformat(),
        } if resolved_key is not None else {
            "period": "utc_day",
            "used": None,
            "limit": None,
            "remaining": None,
            "resets_at": day_end.isoformat(),
        }
    }

    return {
        "identity": identity,
        "entitlements": entitlements,
        "meta": {
            "utc_now": now_utc.isoformat(),
            "latency_ms": latency_ms
        }
    }
